MOCK_Q.push(...[{"id":"mk-n4-c1-1","lv":"N4","t":"kanji","s":"あしたは【都合】がわるいので、べつの日にしてもいいですか。","o":["つごう","とごう","つうごう","つごお"],"a":0,"why":"都 se lee つ en 都合 (no と como en 京都) y 合 es ごう con vocal larga."},{"id":"mk-n4-c1-2","lv":"N4","t":"kanji","s":"この【薬】は食事のあとに飲んでください。","o":["ぐすり","くすり","くずり","くすい"],"a":1,"why":"薬 se lee くすり sin dakuten; las otras opciones cambian una consonante (ぐ, ず) o la última sílaba (い por り)."},{"id":"mk-n4-c1-3","lv":"N4","t":"kanji","s":"弟は毎朝六時に【起きて】走っています。","o":["おきて","おきで","いきて","おこして"],"a":0,"why":"起きる (levantarse) se lee おきる; おこして es 起こして (despertar a otro) y いきて es 生きて."},{"id":"mk-n4-c1-4","lv":"N4","t":"kanji","s":"駅の【出口】で待っています。","o":["しゅつぐち","いりぐち","でぐち","でくち"],"a":2,"why":"出口 lleva rendaku (ぐち); いりぐち es 入口 y しゅつ es la lectura on, que no se usa aquí."},{"id":"mk-n4-c1-5","lv":"N4","t":"kanji","s":"【切手】を三まい買いました。","o":["きて","せって","きって","きりて"],"a":2,"why":"切手 se lee きって con っ; sin la consonante doble o con lectura on (せつ) es incorrecto."},{"id":"mk-n4-c1-6","lv":"N4","t":"kanji","s":"日曜日に家族と【動物】えんへ行きました。","o":["とうぶつ","どぶつ","どうもつ","どうぶつ"],"a":3,"why":"動 es どう (vocal larga) y 物 aquí es ぶつ, no もつ como en 荷物."},{"id":"mk-n4-c1-7","lv":"N4","t":"kanji","s":"その店の【品物】はどれも安いです。","o":["ひんもの","しなもの","しなぶつ","しなもつ"],"a":1,"why":"品物 usa lecturas kun en los dos kanji: しな + もの; mezclar con on (ひん, ぶつ, もつ) es un error típico."},{"id":"mk-n4-c1-8","lv":"N4","t":"kanji","s":"先週からのどがいたくて、【病院】へ行きました。","o":["びょうえん","ひょういん","びよういん","びょういん"],"a":3,"why":"病院 es びょういん: ょ pequeña, vocal larga y dakuten en び."},{"id":"mk-n4-c1-9","lv":"N4","t":"kanji","s":"【寒い】日はあたたかいスープが飲みたくなります。","o":["かんい","つめたい","すずしい","さむい"],"a":3,"why":"寒い (frío de clima) es さむい; かん es la lectura on de 寒 (que no se usa en el adjetivo), つめたい es 冷たい (frío al tacto) y すずしい es 涼しい."},{"id":"mk-n4-c1-10","lv":"N4","t":"kanji","s":"あついので、【冷たい】お茶を飲みたいです。","o":["つめだい","つめたい","ひえたい","さむい"],"a":1,"why":"冷たい (frío al tacto) es つめたい sin dakuten; さむい es 寒い (frío de clima) y ひえ es otra lectura de 冷 (冷える)."},{"id":"mk-n4-c1-11","lv":"N4","t":"kanji","s":"【特別】なことは何もしていません。","o":["とくべつ","とくへつ","どくべつ","とくわけ"],"a":0,"why":"特別 es とくべつ: 特 sin dakuten y 別 con lectura on べつ, no kun わけ."},{"id":"mk-n4-c1-12","lv":"N4","t":"kanji","s":"三時から【教室】でテストがあります。","o":["おしえしつ","きょうしつ","きょうじつ","きょしつ"],"a":1,"why":"教室 es きょうしつ: 教 con vocal larga y 室 sin dakuten; おし es la lectura kun de 教 (教える), que no se usa aquí."},{"id":"mk-n4-c1-13","lv":"N4","t":"kanji","s":"この漢字の【意味】を教えてください。","o":["おみ","いみ","いび","いあじ"],"a":1,"why":"意味 se lee いみ; あじ es la kun de 味 (sabor) y no se usa en esta palabra."},{"id":"mk-n4-c1-14","lv":"N4","t":"kanji","s":"【夕方】から雨が降るそうです。","o":["せきがた","ゆがた","ゆうほう","ゆうがた"],"a":3,"why":"夕方 es ゆうがた con rendaku; ほう es la on de 方 y せき la on de 夕, que aquí no se usan."},{"id":"mk-n4-c1-15","lv":"N4","t":"kanji","s":"【地下鉄】の駅はこの建物の下にあります。","o":["じかてつ","ちかてつ","ちかでつ","ちげてつ"],"a":1,"why":"地 se lee ち aquí (no じ como en 地震) y 鉄 es てつ sin dakuten."},{"id":"mk-n4-c1-16","lv":"N4","t":"kanji","s":"その問題は【自分】で考えてください。","o":["ちぶん","じぶん","じふん","しぶん"],"a":1,"why":"自分 es じぶん: 自 con dakuten (じ) y 分 con rendaku (ぶん)."},{"id":"mk-n4-c1-17","lv":"N4","t":"kanji","s":"妹は【歌】がとても上手です。","o":["うだ","こえ","うた","おと"],"a":2,"why":"歌 se lee うた; おと (音) y こえ (声) son palabras parecidas del mismo campo."},{"id":"mk-n4-c1-18","lv":"N4","t":"kanji","s":"【急いで】いたので、さいふを忘れてしまいました。","o":["きゅういで","およいで","いそんで","いそいで"],"a":3,"why":"急ぐ es いそぐ y su forma て es いそいで; きゅう es la lectura on, que no se usa en el verbo."},{"id":"mk-n4-c1-19","lv":"N4","t":"kanji","s":"道を歩くときは、車に【注意】してください。","o":["しゅうい","ちゅうい","ちゅい","ちゅうもん"],"a":1,"why":"注意 es ちゅうい con vocal larga; ちゅうもん es 注文 (pedido), otra palabra con 注."},{"id":"mk-n4-c1-20","lv":"N4","t":"kanji","s":"兄は【工場】で働いています。","o":["こじょう","くうじょう","こうじょ","こうじょう"],"a":3,"why":"工場 tiene dos vocales largas: こう + じょう; acortar una de ellas es el error típico."},{"id":"mk-n4-c1-21","lv":"N4","t":"kanji","s":"父は【運転】がとても上手です。","o":["うんてい","うてん","うんてん","うんでん"],"a":2,"why":"運転 es うんてん: 転 se lee てん sin dakuten y 運 lleva ん."},{"id":"mk-n4-c1-22","lv":"N4","t":"kanji","s":"【遠い】ところまで歩いて足がいたいです。","o":["とおい","とうい","とい","えんい"],"a":0,"why":"遠い se escribe とおい (con お, no う); えん es la lectura on de 遠 y no se usa en el adjetivo."},{"id":"mk-n4-c1-23","lv":"N4","t":"kanji","s":"冬の【朝】は暗くて起きるのがたいへんです。","o":["あし","ちょう","あさ","ひる"],"a":2,"why":"朝 se lee あさ; ちょう es su lectura on (como en 朝食) y no se usa cuando va sola; ひる es 昼, otra parte del día, y あし es 足."},{"id":"mk-n4-c1-24","lv":"N4","t":"kanji","s":"【世界】のいろいろな国の料理を食べてみたいです。","o":["せけい","せかい","せいかい","せっかい"],"a":1,"why":"世界 se lee せかい con vocal corta en せ; せい y せっ son confusiones de longitud."},{"id":"mk-n4-c1-25","lv":"N4","t":"orth","s":"日曜日に町の【としょかん】で本を借りました。","o":["回書館","図書館","国書館","図書間"],"a":1,"why":"図書館 lleva 図 (mapa, diagrama) y 館 (edificio); 国 y 回 se parecen en forma a 図, y 間 se lee かん pero significa intervalo."},{"id":"mk-n4-c1-26","lv":"N4","t":"orth","s":"先生に【しつもん】してもいいですか。","o":["質門","室問","質問","質聞"],"a":2,"why":"質問 es 質 + 問 (pregunta); 門 y 聞 comparten forma con 問, y 室 se lee しつ pero es habitación."},{"id":"mk-n4-c1-27","lv":"N4","t":"orth","s":"【きょねん】の夏は特にあつかったです。","o":["去生","去年","去午","古年"],"a":1,"why":"去年 usa 去 (pasado) + 年; 古 también significa viejo pero se lee こ, y 午 y 生 se confunden con 年 por la forma."},{"id":"mk-n4-c1-28","lv":"N4","t":"orth","s":"父は【ぎんこう】で働いています。","o":["金行","銀校","鉄行","銀行"],"a":3,"why":"銀行 es 銀 (plata) + 行; 金 y 鉄 son metales parecidos y 校 se lee こう pero es escuela."},{"id":"mk-n4-c1-29","lv":"N4","t":"orth","s":"毎日【うんどう】をしたほうがいいですよ。","o":["運働","運転","運動","通動"],"a":2,"why":"運動 lleva 動 (moverse); 働 (trabajar) se parece mucho en forma, 運転 es conducir y 通 se confunde con 運."},{"id":"mk-n4-c1-30","lv":"N4","t":"orth","s":"朝ごはんを食べながら【しんぶん】を読みます。","o":["新問","新聞","新門","親聞"],"a":1,"why":"新聞 es 新 (nuevo) + 聞 (oír); 問 y 門 comparten la parte 門, y 親 se lee しん pero significa padres."},{"id":"mk-n4-c1-31","lv":"N4","t":"orth","s":"昼は会社の【しょくどう】で食べます。","o":["食堂","飯堂","食道","食室"],"a":0,"why":"食堂 es 食 + 堂 (salón); 道 se lee どう pero es camino, y 室 y 飯 cambian el sentido."},{"id":"mk-n4-c1-32","lv":"N4","t":"orth","s":"来週、京都へ【りょこう】に行きます。","o":["料行","旅校","族行","旅行"],"a":3,"why":"旅行 es 旅 (viaje) + 行; 族 se parece en forma a 旅 y 料 se lee りょう, no りょ."},{"id":"mk-n4-c1-33","lv":"N4","t":"orth","s":"駅まで【あるいて】二十分かかります。","o":["進いて","通いて","歩いて","走いて"],"a":2,"why":"あるく se escribe 歩く; 走 (correr), 進 (avanzar) y 通 (pasar) son verbos de movimiento con otra lectura."},{"id":"mk-n4-c1-34","lv":"N4","t":"orth","s":"寒いので、ドアを【しめて】ください。","o":["開めて","止めて","閉めて","門めて"],"a":2,"why":"しめる (cerrar) es 閉める; 開 es abrir, 門 es portón y 止めて se lee とめて."},{"id":"mk-n4-c1-35","lv":"N4","t":"orth","s":"【あかるい】へやのほうがすきです。","o":["青るい","明るい","暗るい","朝るい"],"a":1,"why":"あかるい es 明るい (luminoso); 暗 es lo contrario, 朝 comparte el sentido de mañana y 青 es azul."},{"id":"mk-n4-c1-36","lv":"N4","t":"orth","s":"お店でお金を【はらって】ください。","o":["引って","押って","取って","払って"],"a":3,"why":"はらう (pagar) se escribe 払う; 引, 押 y 取 son kanji de mano que se leen ひく, おす y とる."},{"id":"mk-n4-c1-37","lv":"N4","t":"orth","s":"【しあい】は三時に始まります。","o":["使合","試合","試会","験合"],"a":1,"why":"試合 es 試 (probar) + 合; 会 también se lee あい y 使 se parece en forma a 試 pero es usar."},{"id":"mk-n4-c1-38","lv":"N4","t":"orth","s":"この【もんだい】はむずかしいですね。","o":["問題","聞題","門題","間題"],"a":0,"why":"問題 lleva 問 (pregunta); 門, 間 y 聞 tienen la misma parte 門 pero significan portón, intervalo y oír."},{"id":"mk-n4-c1-39","lv":"N4","t":"orth","s":"【たいせつ】なものはここにおいてください。","o":["太切","大村","犬切","大切"],"a":3,"why":"たいせつ es 大切; 太 y 犬 solo añaden un punto a 大, y 村 se confunde con 切 por la forma."},{"id":"mk-n4-c1-40","lv":"N4","t":"orth","s":"わたしは東京に【すんで】います。","o":["休んで","住んで","注んで","主んで"],"a":1,"why":"すむ (vivir) se escribe 住む; 主 y 注 comparten el componente 主 y 休 tiene también el radical de persona."},{"id":"mk-n4-c1-41","lv":"N4","t":"ctx","s":"この道を行って、二つ目のかどを右に（　　）ください。","o":["とおって","まわって","わたって","まがって"],"a":3,"why":"Para girar en una esquina se usa 曲がる; 回る es dar vueltas, 渡る cruzar y 通る pasar por un sitio (ninguno va con かどを右に)."},{"id":"mk-n4-c1-42","lv":"N4","t":"ctx","s":"シャワーを（　　）から、朝ごはんを食べます。","o":["あびて","あらって","かけて","はいって"],"a":0,"why":"La colocación fija es シャワーを浴びる; 洗う es lavar algo y 入る va con おふろに."},{"id":"mk-n4-c1-43","lv":"N4","t":"ctx","s":"ピアノを（　　）のがしゅみです。","o":["ひく","うたう","かく","ふく"],"a":0,"why":"Los instrumentos de cuerda o teclado se tocan con 弾く; 吹く es para instrumentos de viento."},{"id":"mk-n4-c1-44","lv":"N4","t":"ctx","s":"薬を飲んだら、ねつが（　　）。","o":["とまりました","さがりました","きえました","おりました"],"a":1,"why":"La fiebre baja con 下がる; 降りる es bajarse de un vehículo y 止まる o 消える no se usan con 熱."},{"id":"mk-n4-c1-45","lv":"N4","t":"ctx","s":"友だちに本を（　　）、まだかえしていません。","o":["もらって","借りて","取って","貸して"],"a":1,"why":"Si todavía hay que devolverlo, lo pediste prestado: 借りる; 貸す es prestar tú y もらう es recibirlo para siempre."},{"id":"mk-n4-c1-46","lv":"N4","t":"ctx","s":"妹は毎週、ピアノ教室に（　　）います。","o":["集まって","通って","進んで","歩いて"],"a":1,"why":"Ir regularmente a un lugar (clases, trabajo) es 通う; los otros verbos no expresan asistencia habitual."},{"id":"mk-n4-c1-47","lv":"N4","t":"ctx","s":"電気を（　　）から、へやを出てください。","o":["さげて","けして","とめて","しめて"],"a":1,"why":"La luz se apaga con 消す; 閉める es cerrar, 止める parar y 下げる bajar."},{"id":"mk-n4-c1-48","lv":"N4","t":"ctx","s":"日本語の（　　）がきれいですね。どこで習いましたか。","o":["意味","発音","文法","答え"],"a":1,"why":"Lo que puede ser きれい al hablar es la pronunciación (発音); la gramática o el significado no se describen así."},{"id":"mk-n4-c1-49","lv":"N4","t":"ctx","s":"パーティーの前に、飲み物を（　　）しておきます。","o":["注意","世話","用意","計画"],"a":2,"why":"Preparar cosas de antemano es 用意する; 注意 es cuidado, 世話 cuidar a alguien y 計画 planear."},{"id":"mk-n4-c1-50","lv":"N4","t":"ctx","s":"このかばんは、パソコンが（　　）のでべんりです。","o":["合う","持つ","通る","入る"],"a":3,"why":"El ordenador cabe en el bolso: 入る; 持つ necesitaría otro sujeto y 合う o 通る no encajan."},{"id":"mk-n4-c1-51","lv":"N4","t":"ctx","s":"バスが急に（　　）、三十分も動きませんでした。","o":["とまって","しまって","やすんで","おりて"],"a":0,"why":"Un vehículo que deja de moverse 止まる; 降りる es bajarse (y lleva を), 休む es descansar y 閉まる es cerrarse."},{"id":"mk-n4-c1-52","lv":"N4","t":"ctx","s":"子どもが生まれてから、毎日がとても（　　）なりました。","o":["いそがしく","ひろく","つよく","おもく"],"a":0,"why":"Con un bebé los días se vuelven ocupados: 忙しい; 強い, 重い y 広い son adjetivos que no se aplican a 毎日."},{"id":"mk-n4-c1-53","lv":"N4","t":"ctx","s":"雨が入ってくるので、まどを（　　）もいいですか。","o":["止めて","閉めて","引いて","切って"],"a":1,"why":"Si hace frío se cierra la ventana: 閉める; 止める, 切る y 引く no van con 窓."},{"id":"mk-n4-c1-54","lv":"N4","t":"ctx","s":"にもつが多いので、タクシーを（　　）ましょう。","o":["のり","とり","もち","よび"],"a":3,"why":"Llamar un taxi es タクシーを呼ぶ; 乗る necesita la partícula に y 取る o 持つ no encajan."},{"id":"mk-n4-c1-55","lv":"N4","t":"ctx","s":"この薬は一日に三回、食事の（　　）に飲んでください。","o":["うしろ","あと","さき","つぎ"],"a":1,"why":"Después de un hecho en el tiempo es あと; うしろ es detrás en el espacio, さき es antes/adelante y つぎ (siguiente) no se usa con 食事の〜に."},{"id":"mk-n4-c1-56","lv":"N4","t":"ctx","s":"一人ではできないので、兄に手つだいを（　　）。","o":["ききました","おしえました","たのみました","いいました"],"a":2,"why":"Pedir un favor es 頼む; 聞く (preguntar), 言う y 教える no van con 手伝いを."},{"id":"mk-n4-c1-57","lv":"N4","t":"ctx","s":"ねつがあるので、今日は会社を（　　）ます。","o":["出かけ","止め","帰り","休み"],"a":3,"why":"Faltar al trabajo es 会社を休む; 止める sería dejar el trabajo y 出かける o 帰る no llevan を con 会社."},{"id":"mk-n4-c1-58","lv":"N4","t":"ctx","s":"新しいパソコンの（　　）がわからないので、店員に聞きました。","o":["理由","使い方","意味","答え"],"a":1,"why":"Lo que se pregunta a un dependiente sobre un aparato es el modo de uso (使い方); el significado, la razón o la respuesta no encajan."},{"id":"mk-n4-c1-59","lv":"N4","t":"ctx","s":"風が強くて、ぼうしが（　　）しまいました。","o":["うごいて","おりて","まわって","とんで"],"a":3,"why":"El viento hace que el sombrero salga volando: 飛ぶ; los otros verbos no expresan eso."},{"id":"mk-n4-c1-60","lv":"N4","t":"ctx","s":"家を出るのがおそくなりましたが、走ったので電車に（　　）。","o":["通いました","間に合いました","合いました","着きました"],"a":1,"why":"Llegar a tiempo es 間に合う; 合う solo es encajar, 着く se usa con 駅に (no con 電車に) y 通う es ir regularmente."}]);

MOCK_Q.push(...[{"id":"mk-n4-c2-1","lv":"N4","t":"para","s":"一日でこの仕事を終わらせるのは【むりです】。","o":["できません","たいへんです","つまらないです","いやです"],"a":0,"why":"«むり» significa que algo no es posible (できない); «たいへん» (duro) o «いや» (desagradable) no implican imposibilidad."},{"id":"mk-n4-c2-2","lv":"N4","t":"para","s":"かいぎの時間がきまったら、みんなに【知らせて】ください。","o":["考えて","教えて","かえて","聞いて"],"a":1,"why":"«知らせる» es informar a otros, es decir «教える»; «聞く» es lo contrario (preguntar) y «かえる» es cambiar."},{"id":"mk-n4-c2-3","lv":"N4","t":"para","s":"走って行ったので、電車に【間に合いました】。","o":["おくれませんでした","とまりませんでした","待ちませんでした","のれませんでした"],"a":0,"why":"«間に合う» es llegar a tiempo, o sea no llegar tarde; «のれませんでした» dice justo lo contrario."},{"id":"mk-n4-c2-4","lv":"N4","t":"para","s":"母はもう晩ご飯を【用意して】います。","o":["あらって","しょくじして","じゅんびして","注文して"],"a":2,"why":"«用意する» equivale a «準備する» (preparar); «注文» es pedir en un restaurante y «食事する» es comer."},{"id":"mk-n4-c2-5","lv":"N4","t":"para","s":"今日の午後は【ひまです】。","o":["時間がありません","お金がありません","用事がありません","元気がありません"],"a":2,"why":"«ひま» es tener tiempo libre, sin nada que hacer; «時間がない» es exactamente lo contrario."},{"id":"mk-n4-c2-6","lv":"N4","t":"para","s":"しゅうまつは【たいてい】家で本を読んでいます。","o":["ぜんぜん","ときどき","ずっと","だいたい"],"a":3,"why":"«たいてい» significa casi siempre, igual que «だいたい»; «ときどき» es a veces y «ずっと» es todo el tiempo sin parar."},{"id":"mk-n4-c2-7","lv":"N4","t":"para","s":"友だちに【うそ】を言ってはいけません。","o":["とても大事なこと","ほんとうではないこと","だれも知らないこと","ほんとうに悪いこと"],"a":1,"why":"«うそ» es una mentira, algo que no es verdad; «悪いこと» es más general y no significa lo mismo."},{"id":"mk-n4-c2-8","lv":"N4","t":"para","s":"あの店は【品物】が多いです。","o":["作っている物","着ている物","食べている物","売っている物"],"a":3,"why":"«品物» son los artículos o mercancías que vende una tienda, no lo que se fabrica, se come o se lleva puesto."},{"id":"mk-n4-c2-9","lv":"N4","t":"para","s":"今朝は【けっこう】寒いですね。","o":["ちょっと","ぜんぜん","だんだん","かなり"],"a":3,"why":"«結構» como adverbio significa bastante (かなり); «ちょっと» es poco y «だんだん» es poco a poco."},{"id":"mk-n4-c2-10","lv":"N4","t":"para","s":"三月になって、【だんだん】あたたかくなってきました。","o":["すぐに","少しずつ","とても","急に"],"a":1,"why":"«だんだん» es gradualmente, poco a poco; «急に» y «すぐに» expresan rapidez, lo contrario de un cambio gradual."},{"id":"mk-n4-c2-11","lv":"N4","t":"para","s":"今日の試験は【やさしかった】です。","o":["かんたんだった","むずかしかった","しんせつだった","たいへんだった"],"a":0,"why":"Aquí «やさしい» (易しい) significa fácil; la trampa es «優しい» (amable), que sería «しんせつ»."},{"id":"mk-n4-c2-12","lv":"N4","t":"para","s":"わたしはテレビを【あまり】見ません。","o":["毎日見ます","少ししか見ません","よく見ます","ぜんぜん見ません"],"a":1,"why":"«あまり〜ない» indica poca cantidad o frecuencia, lo mismo que «少ししか〜ない»; «ぜんぜん〜ない» es nunca en absoluto, un grado distinto, y las otras dos dicen lo contrario."},{"id":"mk-n4-c2-13","lv":"N4","t":"usage","w":"用意","o":["明日の天気を用意してください。","パーティーの飲み物はわたしが用意します。","来年の試験のために、毎日日本語を用意しています。","駅で友だちを三十分用意しました。"],"a":1,"why":"«用意» es preparar o tener listo algo concreto (bebidas); no se usa para estudiar un idioma (勉強), esperar a alguien (待つ) ni consultar el tiempo (調べる)."},{"id":"mk-n4-c2-14","lv":"N4","t":"usage","w":"注意","o":["旅行の計画を注意しました。","友だちのたんじょう日に花を注意しました。","毎朝、新聞を注意しています。","道がぬれているので、足もとに注意してください。"],"a":3,"why":"«注意する» es tener cuidado o prestar atención a un peligro; la trampa es confundirlo con «注文» (pedir flores) o con leer o planear."},{"id":"mk-n4-c2-15","lv":"N4","t":"usage","w":"都合","o":["今日は体の都合が悪くて、学校を休みました。","来週の金曜日なら都合がいいです。","新しいパソコンの都合はどうですか。","友だちと都合をして、三時に会います。"],"a":1,"why":"«都合» se refiere a la conveniencia de horarios o circunstancias; para el estado del cuerpo o de una máquina se dice «具合/調子» y para quedar se usa «約束»."},{"id":"mk-n4-c2-16","lv":"N4","t":"usage","w":"特に","o":["父は特に会社員です。","果物の中で、特にりんごがすきです。","試験に特にごうかくしました。","毎日特に六時に起きます。"],"a":1,"why":"«特に» destaca un elemento entre otros (especialmente); no expresa dificultad, costumbre diaria ni una simple descripción."},{"id":"mk-n4-c2-17","lv":"N4","t":"usage","w":"むり","o":["あの人はむりな人で、いつもおくれて来ます。","先生のせつめいはむりでよく分かりませんでした。","一日で本を十さつ読むのはむりです。","今日はむりが悪いので、休みます。"],"a":2,"why":"«むり» es algo imposible o irrazonable; no describe a una persona informal, el estado de salud («都合/調子») ni una explicación difícil."},{"id":"mk-n4-c2-18","lv":"N4","t":"usage","w":"急に","o":["毎朝急に学校へ行きます。","姉は日本語が急に上手です。","急に出てください、電車が来ますよ。","電車が急に止まって、びっくりしました。"],"a":3,"why":"«急に» significa de repente, un cambio inesperado; para pedir prisa se dice «急いで» y no se combina con hábitos ni con estados permanentes."},{"id":"mk-n4-c2-19","lv":"N4","t":"usage","w":"大事","o":["電車の中では大事な声で話してはいけません。","これは父からもらった大事な時計です。","大事な雨で試合が中止になりました。","兄は大事な病気で三日休みました。"],"a":1,"why":"«大事» significa importante o valioso; para lluvia fuerte se dice «ひどい», para enfermedad grave «重い» y para la voz alta «大きい», nunca «大事»."},{"id":"mk-n4-c2-20","lv":"N4","t":"usage","w":"世話","o":["母は毎晩だいどころで世話をします。","この店は世話がいいので、よく来ます。","やまださんにパソコンの世話をしてもらいました。","旅行の間、となりの人が犬の世話をしてくれました。"],"a":3,"why":"«世話をする» es cuidar de personas o animales; cocinar es «料理», arreglar un ordenador no es «世話» y la atención de una tienda es «サービス»."},{"id":"mk-n4-c2-21","lv":"N4","t":"usage","w":"安心","o":["今日は安心な天気なので、さんぽに行きましょう。","安心なお茶を一つください。","試験にごうかくしたと聞いて、安心しました。","この問題は安心なので、すぐできました。"],"a":2,"why":"«安心» es sentirse tranquilo tras una preocupación; no significa fácil («かんたん»), ni describe una bebida barata o caliente («安い/熱い»), ni el buen tiempo («いい天気»)."},{"id":"mk-n4-c2-22","lv":"N4","t":"usage","w":"だんだん","o":["四月になって、だんだんあたたかくなってきました。","兄はだんだんせが高い人です。","電車がだんだん駅に着きました。","さいふをだんだん忘れてしまいました。"],"a":0,"why":"«だんだん» acompaña cambios graduales; no sirve para una acción puntual (llegar, olvidar) ni para describir un estado fijo (ser alto)."},{"id":"mk-n4-c2-23","lv":"N4","t":"usage","w":"ちょうど","o":["このくつはちょうど大きくて、はけません。","ちょうど雨が降るかもしれません。","今ちょうど昼ご飯を食べているところです。","駅までちょうど遠いので、バスで行きます。"],"a":2,"why":"«ちょうど» significa justo o exactamente (en este momento, la cantidad exacta); no sirve como grado de un adjetivo («ちょっと大きい», «かなり遠い») ni acompaña a una probabilidad."},{"id":"mk-n4-c2-24","lv":"N4","t":"usage","w":"かならず","o":["わたしはかならずコーヒーがすきです。","出かける前に、かならず電気をけしてください。","今日はかならずさむいですね。","弟はかならず来ないと思います。"],"a":1,"why":"«かならず» (sin falta) acompaña acciones seguras u obligaciones; no sirve como grado de un estado (frío, gustar), donde iría «とても», ni se combina con una negación («来ない»)."},{"id":"mk-n4-c2-25","lv":"N4","t":"gram","s":"駅に（　　）、電話してください。","o":["着いても","着いたら","着くと","着くなら"],"a":1,"why":"Con una petición en la frase principal se usa «〜たら»; «〜と» no admite órdenes, «〜なら» da consejo sobre un plan y «〜ても» significa aunque."},{"id":"mk-n4-c2-26","lv":"N4","t":"gram","s":"「日本語の本を買いたいんですが。」「本（　　）、駅前の本屋が安いですよ。」","o":["でも","ので","なら","から"],"a":2,"why":"«N+なら» retoma el tema que acaba de mencionar el interlocutor para dar un consejo; «でも» (incluso), «ので» y «から» (porque) no encajan."},{"id":"mk-n4-c2-27","lv":"N4","t":"gram","s":"このボタンを（　　）、ドアが開きます。","o":["押したり","押すと","押しても","押すなら"],"a":1,"why":"«〜と» expresa una consecuencia automática y natural (al pulsar, se abre); «〜なら» presenta un supuesto del interlocutor, «〜ても» significa aunque y «〜たり» enumera acciones."},{"id":"mk-n4-c2-28","lv":"N4","t":"gram","s":"電車の中で、知らない人に足を（　　）。","o":["ふませました","ふみました","ふんでいました","ふまれました"],"a":3,"why":"La persona que sufre la acción es el sujeto y el agente lleva «に», por lo que hace falta la pasiva «ふまれる»; «ふませる» sería el causativo."},{"id":"mk-n4-c2-29","lv":"N4","t":"gram","s":"弟に大事な本を（　　）、困っています。","o":["なくして","なくさせて","なくされて","なくなって"],"a":2,"why":"Pasiva de perjuicio: el hermano perdió mi libro y yo lo sufro; «なくして» sería que lo perdí yo y «なくなって» es intransitivo sin agente."},{"id":"mk-n4-c2-30","lv":"N4","t":"gram","s":"母は子どもにやさいを（　　）。","o":["食べてみました","食べさせました","食べておきました","食べさせられました"],"a":1,"why":"La madre hace comer al niño, de ahí el causativo «食べさせる» con el niño marcado con «に»; «食べさせられる» sería que a ella la obligaron, y «てみる» u «ておく» no admiten ese «子どもに»."},{"id":"mk-n4-c2-31","lv":"N4","t":"gram","s":"子どものとき、毎日ピアノを（　　）。","o":["習わされました","習われました","習っておきました","習わせました"],"a":0,"why":"El hablante fue obligado por sus padres, por eso el causativo-pasivo «習わされる»; «習わせる» sería obligar a otro."},{"id":"mk-n4-c2-32","lv":"N4","t":"gram","s":"空が暗いですね。午後は雨が（　　）。","o":["降ることにします","降るようにします","降るつもりです","降るかもしれません"],"a":3,"why":"Para una suposición sobre el tiempo se usa «〜かもしれない»; «つもり», «ようにする» y «ことにする» expresan voluntad y no sirven con la lluvia."},{"id":"mk-n4-c2-33","lv":"N4","t":"gram","s":"たなかさんはきのう出発したから、もう東京に（　　）。","o":["着いてほしいです","着いてもいいです","着いているはずです","着くつもりです"],"a":2,"why":"«〜はずだ» es una deducción lógica basada en un dato (salió ayer); «つもり» es intención propia, «てほしい» deseo y «てもいい» permiso."},{"id":"mk-n4-c2-34","lv":"N4","t":"gram","s":"天気よほう（　　）、明日はゆきだそうです。","o":["について","によって","によると","にとって"],"a":2,"why":"La fuente de una información con «〜そうだ» se marca con «〜によると»; «について» es acerca de, «にとって» para y «によって» según varía o por medio de."},{"id":"mk-n4-c2-35","lv":"N4","t":"gram","s":"このケーキ、とても（　　）ですね。","o":["おいしくそう","おいしそう","おいしさそう","おいしいそう"],"a":1,"why":"El «〜そう» de apariencia se une a la raíz del adjetivo い (おいし+そう); «おいしいそう» sería la forma de rumor y las otras no existen."},{"id":"mk-n4-c2-36","lv":"N4","t":"gram","s":"先生は今、教室に（　　）。","o":["おります","まいります","いたします","いらっしゃいます"],"a":3,"why":"Para el profesor se usa el honorífico «いらっしゃる» (estar); «おる», «まいる» e «いたす» son formas humildes que solo valen para hablar de uno mismo."},{"id":"mk-n4-c2-37","lv":"N4","t":"gram","s":"「はじめまして。やまだと（　　）。」","o":["いらっしゃいます","申します","おっしゃいます","いただきます"],"a":1,"why":"Al presentarse se usa el humilde «申す»; «おっしゃる» e «いらっしゃる» son honoríficos para otros y «いただく» es recibir o comer."},{"id":"mk-n4-c2-38","lv":"N4","t":"gram","s":"電車（　　）バスのほうが安いです。","o":["より","だけ","ほど","から"],"a":0,"why":"La comparación «AよりBのほうが» exige «より» tras el elemento inferior; «ほど» solo se usa con negación y «から» o «だけ» no comparan."},{"id":"mk-n4-c2-39","lv":"N4","t":"gram","s":"今年の冬は去年（　　）寒くないです。","o":["だけ","しか","ぐらい","ほど"],"a":3,"why":"«Aは Bほど〜ない» indica que A no llega al grado de B; «ぐらい» expresa aproximación y «だけ» o «しか» limitan cantidad."},{"id":"mk-n4-c2-40","lv":"N4","t":"gram","s":"「もう昼ご飯を食べましたか。」「いいえ、今から（　　）です。」","o":["食べたばかり","食べるところ","食べているところ","食べたところ"],"a":1,"why":"«今から» marca que la acción está a punto de empezar, por eso «Vるところ»; «たところ» y «たばかり» indican que acaba de terminar."},{"id":"mk-n4-c2-41","lv":"N4","t":"gram","s":"三か月前に日本に（　　）ので、まだ漢字があまり読めません。","o":["来るばかりな","来たところな","来るところな","来たばかりな"],"a":3,"why":"«〜たばかり» admite un tiempo transcurrido (tres meses) con sentido de «hace poco»; «〜たところ» solo vale para el instante justo después."},{"id":"mk-n4-c2-42","lv":"N4","t":"gram","s":"けんこうのために、毎日やさいを（　　）しています。","o":["食べるように","食べるために","食べたように","食べるそうに"],"a":0,"why":"«〜ようにする» expresa el esfuerzo por mantener un hábito; «ために» no se combina con «している» así y las otras formas no tienen sentido."},{"id":"mk-n4-c2-43","lv":"N4","t":"gram","s":"毎日れんしゅうして、漢字が（　　）なりました。","o":["書けるように","書けるそうに","書けることに","書けるために"],"a":0,"why":"Un cambio de capacidad se expresa con «potencial + ようになる»; «ために» (para) y «ことに» (decidir) no se usan con «なる» de este modo."},{"id":"mk-n4-c2-44","lv":"N4","t":"gram","s":"後ろの人にも（　　）、大きい声で話してください。","o":["聞こえるのに","聞こえるように","聞こえると","聞こえるために"],"a":1,"why":"Con un verbo no volitivo (聞こえる) la finalidad se marca con «〜ように»; «ために» exige verbo volitivo y «のに» o «と» cambian el sentido."},{"id":"mk-n4-c2-45","lv":"N4","t":"gram","s":"来週のかいぎには、やまださんにも（　　）。","o":["来てみたいです","来てほしいです","来たがります","来たいです"],"a":1,"why":"El deseo de que otra persona haga algo se expresa con «Nに〜てほしい»; «〜たい» es deseo propio y «〜たがる» describe a un tercero sin «に»."},{"id":"mk-n4-c2-46","lv":"N4","t":"gram","s":"すみませんが、この漢字の読み方を（　　）。","o":["教えておきませんか","教えていただけませんか","教えさせませんか","教えてあげませんか"],"a":1,"why":"Para pedir un favor con cortesía se usa «〜ていただけませんか»; «てあげる» es hacer un favor a otro y «させる» u «おく» no son peticiones."},{"id":"mk-n4-c2-47","lv":"N4","t":"gram","s":"「その仕事、ぜひわたしに（　　）。」","o":["やらせられてください","やらせてください","やってもらってください","やられてください"],"a":1,"why":"Para pedir permiso de hacer algo uno mismo se usa «causativo + てください»; la pasiva «やられる» y el causativo-pasivo no sirven aquí."},{"id":"mk-n4-c2-48","lv":"N4","t":"gram","s":"日本語は勉強（　　）おもしろくなります。","o":["したらしたほど","すればするほど","するとするほど","するならするほど"],"a":1,"why":"La estructura fija «〜ば〜ほど» (cuanto más…) exige la forma condicional ば repetida con el verbo; con «と», «たら» o «なら» no existe."},{"id":"mk-n4-c2-49","lv":"N4","t":"gram","s":"朝ご飯を（　　）、学校に来てしまいました。","o":["食べなずに","食べないずに","食べずに","食べずで"],"a":2,"why":"«〜ずに» (sin hacer) se forma con la raíz negativa: 食べ+ずに; las otras opciones mezclan «ない» o «で» y son formas inexistentes."},{"id":"mk-n4-c2-50","lv":"N4","t":"gram","s":"エアコンを（　　）、出かけてしまいました。","o":["つけたところ","つけたばかり","つけたうち","つけたまま"],"a":3,"why":"«〜たまま» indica que un estado se deja sin cambiar (encendido); «ばかり» y «ところ» hablan del tiempo justo después y «うち» no va con た."},{"id":"mk-n4-c2-51","lv":"N4","t":"gram","s":"子どもが（　　）、そうじをしてしまおう。","o":["ねているうちに","ねているところに","ねているまま","ねているあいだを"],"a":0,"why":"«〜ているうちに» aprovecha un periodo antes de que cambie la situación; «あいだを» lleva partícula incorrecta y «ところに» es el instante justo."},{"id":"mk-n4-c2-52","lv":"N4","t":"gram","s":"つくえの上に手紙が（　　）。","o":["おいてあります","おいてしまいます","おいています","おいておきます"],"a":0,"why":"Un estado resultante de una acción intencional se describe con «Vてある» y el objeto marcado con «が»; las otras necesitan «を» y un agente."},{"id":"mk-n4-c2-53","lv":"N4","t":"gram","s":"薬を（　　）、まだねつが下がりません。","o":["飲んだので","飲んだのに","飲んだなら","飲んだから"],"a":1,"why":"«〜のに» marca un resultado contrario a lo esperado (tomé medicina pero no baja); «ので» y «から» expresan causa y «なら» condición."},{"id":"mk-n4-c2-54","lv":"N4","t":"gram","s":"この店は料理もおいしい（　　）、料金も安いので、よく来ます。","o":["て","が","と","し"],"a":3,"why":"«〜し〜し» enumera razones del mismo signo con «も»; «が» indicaría contraste, «て» exigiría «おいしくて» y «と» no une oraciones."}]);

MOCK_Q.push(...[{"id":"mk-n4-c3-1","lv":"N4","t":"order","pre":"たんじょう日に","parts":["父が","買ってくれた","時計を","なくして"],"post":"しまいました。","why":"「父が買ってくれた」es la oración relativa que modifica a 「時計」; la trampa es poner 「なくして」antes del sustantivo, lo que rompe la relativa."},{"id":"mk-n4-c3-2","lv":"N4","t":"order","pre":"この薬は","parts":["食事の","後で","飲む","ように"],"post":"言われました。","why":"「〜ように言われる」(me dijeron que...) exige el verbo en forma diccionario justo antes de 「ように」; 「食事の後で」debe ir unido porque 「の」une sustantivos."},{"id":"mk-n4-c3-3","lv":"N4","t":"order","pre":"あの店はねだんが","parts":["安い","だけでなく","味も","いい"],"post":"ので、よく行きます。","why":"「ねだんが」obliga a que 「安い」vaya primero; 「〜だけでなく〜も」(no solo... sino también) fija el orden: lo básico primero y lo añadido con 「も」después."},{"id":"mk-n4-c3-4","lv":"N4","t":"order","pre":"電車が","parts":["止まって","いる","間に","本を"],"post":"読みました。","why":"「〜ている間に」(mientras...) necesita el verbo en 〜ている antes de 「間に」; la trampa es separar 「止まって」de 「いる」o poner 「本を」delante."},{"id":"mk-n4-c3-5","lv":"N4","t":"order","pre":"天気よほうでは、あしたは","parts":["雨が","降る","かもしれない","と"],"post":"言っていました。","why":"La cita indirecta 「〜と言っていました」recoge toda la frase 「雨が降るかもしれない」; 「かもしれない」va tras la forma diccionario y antes de 「と」."},{"id":"mk-n4-c3-6","lv":"N4","t":"order","pre":"","parts":["日本語が","話せる","ように","なりたい"],"post":"と思って、毎日れんしゅうしています。","why":"「〜ようになる」(llegar a poder) toma la forma potencial 「話せる」antes de 「ように」; el objeto de la potencial se marca con 「が」, no con 「を」."},{"id":"mk-n4-c3-7","lv":"N4","t":"order","pre":"先生に","parts":["しゅくだいを","出すのを","忘れて","しまって"],"post":"、しかられました。","why":"「出すのを忘れる」nominaliza la acción olvidada con 「の」; 「〜てしまう」expresa pesar y va al final, justo antes de la consecuencia."},{"id":"mk-n4-c3-8","lv":"N4","t":"order","pre":"このパソコンは","parts":["古くて","使いにくい","から","新しいのを"],"post":"買おうと思っています。","why":"Los adjetivos se encadenan con la forma て 「古くて使いにくい」; 「から」(porque) cierra la causa y 「新しいのを」(uno nuevo) es el objeto de 「買おう」."},{"id":"mk-n4-c3-9","lv":"N4","t":"order","pre":"かいぎが","parts":["始まる","前に","しりょうを","コピーして"],"post":"おいてください。","why":"「〜前に」(antes de) va con la forma diccionario 「始まる」, cuyo sujeto es 「かいぎが」; 「〜ておく」(dejar preparado) se forma con 「コピーして」+「おいて」."},{"id":"mk-n4-c3-10","lv":"N4","t":"order","pre":"漢字は","parts":["書けば","書く","ほど","おぼえられる"],"post":"ようになります。","why":"La estructura 「〜ば〜ほど」(cuanto más... más) se forma con la condicional 「書けば」seguida de la forma diccionario 「書く」y 「ほど」; invertirlas es el error típico."},{"id":"mk-n4-c3-11","lv":"N4","t":"order","pre":"きのう","parts":["駅で","会った","人は","だれ"],"post":"ですか。","why":"「駅で会った」es la oración relativa que describe a 「人」; 「人は」lleva el tema y 「だれですか」es el predicado. Poner 「人は」al principio deja a 「会った」sin sustantivo."},{"id":"mk-n4-c3-12","lv":"N4","t":"order","pre":"母は弟に","parts":["きらいな","やさいを","食べさせよう","と"],"post":"しています。","why":"「きらいな」modifica a 「やさい」; el causativo en volitiva 「食べさせよう」+「としている」significa «intenta hacer que coma»."},{"id":"mk-n4-c3-13","lv":"N4","t":"order","pre":"電車の中で足を","parts":["ふんだ","人は","何も","言わずに"],"post":"行ってしまいました。","why":"「足をふんだ」es la relativa que modifica a 「人」; 「何も言わずに」(sin decir nada) exige 「何も」justo antes del verbo negativo en 〜ずに."},{"id":"mk-n4-c3-14","lv":"N4","t":"order","pre":"エアコンを","parts":["つけた","まま","ねて","しまった"],"post":"ので、のどがいたいです。","why":"「〜たまま」(dejando algo como está) se forma con la forma た 「つけた」+「まま」; después viene la acción principal 「ねてしまった」con matiz de pesar."},{"id":"mk-n4-c3-15","lv":"N4","t":"cloze","p":"先週の日曜日、友だちと海へ行きました。朝は天気がよかった(1)、午後から急に雨が降り(2)。かさを持っていなかったので、二人ともぬれてしまいました。でも、海で食べた魚はとてもおいしかったです。(3)また行きたいと思っています。今度は天気よほうを(4)から行くつもりです。","q":[{"o":["のに","ので","から","し"],"a":0},{"o":["終わりました","始めました","つづけました","やすかったです"],"a":1},{"o":["だから","それから","ところで","でも"],"a":0},{"o":["見る","見ない","見て","見た"],"a":2}],"why":"(1) 「のに」marca el contraste entre el buen tiempo y la lluvia; (2) 「降り始める」= empezó a llover; (3) 「だから」une la comida rica con el deseo de volver; (4) 「〜てから」(después de) exige la forma て, no la forma た con 「から」causal."},{"id":"mk-n4-c3-16","lv":"N4","t":"cloze","p":"山本さん\nおつかれさまです。来週の月曜日のかいぎ(1)、しりょうをお送りします。かいぎの前に読んでおいて(2)。分からないところがあったら、(3)聞いてください。それでは、月曜日に(4)。\n木村","q":[{"o":["によって","によると","について","にとって"],"a":2},{"o":["くださいましたか","いただきましたか","もらいましたか","いただけませんか"],"a":3},{"o":["いつか","いつでも","いつも","いつ"],"a":1},{"o":["お待ちになっております","待たせております","待っていらっしゃいます","お待ちしております"],"a":3}],"why":"(1) 「〜について」= acerca de; (2) la petición cortés usa potencial negativa 「〜ていただけませんか」, no formas en pasado; (3) 「いつでも」= en cualquier momento; (4) el humilde 「お〜する／しております」se usa para la acción propia, mientras que 「お〜になる」e 「いらっしゃる」son honoríficos para otros."},{"id":"mk-n4-c3-17","lv":"N4","t":"cloze","p":"わたしは去年から毎朝走っています。(1)は五分走るだけでつかれていましたが、今は三十分(2)走れるようになりました。走り始めてから、よくねられる(3)なりました。医者にも「いいしゅうかんですね」と言われました。これからも(4)つづけたいと思います。","q":[{"o":["始めるころ","始めたまま","始めたところ","始めたころ"],"a":3},{"o":["しか","ぐらい","ずつ","ごろ"],"a":1},{"o":["ように","そうに","ことに","ために"],"a":0},{"o":["むりをしないなら","むりをしないで","むりをしないと","むりをしなくて"],"a":1}],"why":"(1) 「始めたころ」= en la época en que empecé (pasado), 「始めたところ」sería el instante justo después; (2) 「ぐらい」indica cantidad aproximada, 「ごろ」es solo para horas y 「ずつ」significa «de cada vez»; (3) 「〜ようになる」expresa el cambio de capacidad; (4) 「〜ないで」(sin hacer) acompaña a otra acción, 「なくて」indica causa."},{"id":"mk-n4-c3-18","lv":"N4","t":"cloze","p":"駅前のパン屋が、来月から新しい店になる(1)聞きました。店の人(2)話では、店は広くなって、中で食べられるところもできるそうです。今の店は小さくて、朝はいつもたくさんの人が(3)、入るのに時間がかかります。新しい店ができたら、コーヒーを(4)パンを食べられるのが楽しみです。","q":[{"o":["て","と","を","のに"],"a":1},{"o":["と","に","が","の"],"a":3},{"o":["ならべていて","ならんでいて","ならんであって","ならべてあって"],"a":1},{"o":["飲みながらも","飲みながら","飲むながら","飲んでながら"],"a":1}],"why":"(1) 「〜と聞く」= oír que...; una oración completa no se une a 聞く con 「を」ni con 「て」; (2) 「店の人の話」une sustantivos con 「の」; (3) 「ならぶ」es intransitivo y la gente hace cola con 「〜ている」, mientras que 「ならべる」/「〜てある」son para cosas colocadas; (4) 「〜ながら」va con la raíz de ます, y 「ながらも」significa «aunque»."},{"id":"mk-n4-c3-19","lv":"N4","t":"read","p":"ゆきへ\n今日はおばあちゃんの病院に行くので、帰りが七時ごろになります。れいぞうこにカレーがあるから、あたためて食べてください。ご飯はもうたいてあります。それから、六時ごろ、インターネットでたのんだ本がとどくので、うけ取っておいてください。\nお母さんより","q":[{"q":"ゆきさんは、何をしなくてもいいですか。","o":["本をうけ取ること","晩ご飯を食べること","カレーをあたためること","ご飯をたくこと"],"a":3,"why":"「ご飯はもうたいてあります」indica que el arroz ya está hecho (〜てある = preparado de antemano); lo demás son cosas que la madre le pide hacer."}]},{"id":"mk-n4-c3-20","lv":"N4","t":"read","p":"学生のみなさん\n来週の金曜日のテストについて、お知らせします。テストは九時から始まります。教室はいつもと同じではありません。図書館のとなりの大きい教室でしますから、注意してください。えんぴつとけしゴムだけ持ってきてください。じしょは使えません。じゅぎょうで習った漢字が出ますから、よくふくしゅうしておいてください。\n小林","q":[{"q":"テストの日、学生はどうしなければなりませんか。","o":["いつもの教室に九時に行く","大きい教室に八時に行く","図書館にじしょを持って行く","いつもとちがう教室に九時に行く"],"a":3,"why":"El texto dice que el aula no es la de siempre (「いつもと同じではありません」) y que empieza a las nueve; el diccionario no se puede usar y el lugar es el aula junto a la biblioteca, no la biblioteca."}]},{"id":"mk-n4-c3-21","lv":"N4","t":"read","p":"住んでいる人へのお知らせ\n十月十日（金）の午前九時から午後三時まで、水道の工事をします。この時間は水が出ません。前の日に、使う水を用意しておいてください。工事が終わる時間は、少し早くなることもあります。工事中は音がしますが、どうぞよろしくおねがいします。\nさくらマンション","q":[{"q":"この文を読んだ人は、何をしなければなりませんか。","o":["十月九日に、水を用意する","工事の間、へやを出ておく","十月十日の朝に、水を用意する","午後三時すぎに水道を使わない"],"a":0,"why":"「前の日に」se refiere al día anterior al 10 de octubre, es decir, el día 9; el agua vuelve a las tres y nadie pide salir de casa."}]},{"id":"mk-n4-c3-22","lv":"N4","t":"read","p":"今日ははじめて一人で電車にのって、おばの家に行った。駅できっぷを買うのに時間がかかって、電車に間に合わないかと思ったが、だいじょうぶだった。おばの家では、いとことこうえんであそんだり、料理を手つだったりした。帰りの電車の中でねてしまって、駅をひとつ通りすぎてしまった。でも、とても楽しい一日だった。","q":[{"q":"この人は、どうして駅を通りすぎてしまいましたか。","o":["はじめて一人で電車にのったから","電車の中でねむってしまったから","きっぷを買うのに時間がかかったから","電車に間に合わなかったから"],"a":1,"why":"「帰りの電車の中でねてしまって、駅をひとつ通りすぎて」: se pasó de estación por dormirse; lo del billete ocurrió en la ida y al final sí llegó a tiempo."},{"q":"この人は今日のことをどう思っていますか。","o":["一人で電車にのるのはこわかった","何も問題がなくて楽しかった","たいへんなこともあったが、楽しかった","駅を通りすぎて、つまらなかった"],"a":2,"why":"Hubo problemas (el billete, pasarse de estación), pero la frase final 「でも、とても楽しい一日だった」muestra que, a pesar de ellos, lo pasó bien."}]},{"id":"mk-n4-c3-23","lv":"N4","t":"read","p":"森さん\nおつかれさまです。今日、電車がおくれていて、会社に着くのが三十分ぐらいおそくなりそうです。十時からのかいぎには間に合わないかもしれません。もうしわけありませんが、わたしの代わりに、しりょうをみんなにくばっておいてもらえませんか。しりょうはわたしのつくえの上においてあります。よろしくおねがいします。\n高木","q":[{"q":"高木さんは森さんに何をしてほしいと言っていますか。","o":["しりょうをつくえの上におくこと","かいぎの時間をおそくすること","電車の時間をしらべること","しりょうをみんなにわたすこと"],"a":3,"why":"「わたしの代わりに、しりょうをみんなにくばっておいてもらえませんか」: pide repartir (くばる = わたす) los documentos; estos ya están sobre la mesa, y no pide cambiar la hora de la reunión."}]},{"id":"mk-n4-c3-24","lv":"N4","t":"read","p":"日本語教室のお知らせ\nしみんセンターで、外国人のための日本語教室を始めます。毎週土曜日の午前十時から十二時まで、ボランティアの先生と話したり、漢字をべんきょうしたりします。料金はかかりませんが、はじめの日にテキスト代として五百円がいります。入りたい人は、センターに来て、名前を書いてください。電話でもできます。","q":[{"q":"この教室に入りたい人は、どうすればいいですか。","o":["土曜日の十時に教室に行く","センターに行くか、電話をする","五百円を持って先生に会う","センターにテキストを買いに行く"],"a":1,"why":"La inscripción se hace yendo al centro a escribir el nombre o por teléfono (「電話でもできます」); los 500 yenes se pagan el primer día, no sirven para inscribirse."}]},{"id":"mk-n4-c3-25","lv":"N4","t":"read","p":"リンさん\n先週は、わたしのたんじょう日パーティーに来てくれて、ありがとうございました。リンさんが作ってくれた国の料理は、みんな「おいしい」と言っていました。作り方を教えてもらえませんか。今度、わたしも家で作ってみたいです。それから、パーティーの写真ができたので、来週会った時にわたします。楽しみにしていてください。\nアンナ","q":[{"q":"アンナさんは、リンさんにどんなことをたのんでいますか。","o":["今度家にあそびに来ること","パーティーの写真をとること","もう一度料理を作ること","料理の作り方を教えること"],"a":3,"why":"La petición es 「作り方を教えてもらえませんか」; Anna quiere cocinar ella misma (「わたしも家で作ってみたい」), y las fotos ya están hechas y las entregará ella."}]},{"id":"mk-n4-c3-26","lv":"N4","t":"read","p":"テニス教室のみなさんへ\n今週の水曜日のれんしゅうは、雨のためにできなくなりました。その代わりに、日曜日の午後二時から四時までれんしゅうをします。ばしょはいつもと同じです。日曜日に来られない人は、金曜日までに先生に知らせてください。来月の試合に出る人は、日曜日はかならず来てください。","q":[{"q":"日曜日のれんしゅうに来られない人は、どうしますか。","o":["日曜日に先生に電話する","金曜日までに先生に言う","来月の試合に出ない","水曜日に先生に言う"],"a":1,"why":"「日曜日に来られない人は、金曜日までに先生に知らせてください」: hay que avisar antes del viernes; el miércoles no hay práctica y no se dice nada de dejar el partido."},{"q":"来月の試合に出る人について、正しいものはどれですか。","o":["水曜日のれんしゅうに出なければならない","金曜日に先生に会わなければならない","日曜日は休んでもいい","日曜日のれんしゅうに出なければならない"],"a":3,"why":"「かならず来てください」dirigido a quienes juegan el partido significa que la asistencia del domingo es obligatoria; la del miércoles se canceló."}]}]);

MOCK_Q.push(...[{"id":"mk-n4-c4-1","lv":"N4","t":"readm","p":"わたしは去年の春、仕事で東京から小さな町に引っこしました。はじめは知っている人が一人もいなくて、休みの日は家でテレビを見るだけでした。ある日、きんじょのおばあさんが「うちでとれたやさいです」と言って、大きなだいこんをくれました。わたしは料理があまり上手ではないので、どう使えばいいか分からなくて困りました。でも、もらった物をすてるのはいやだったので、インターネットで作り方をしらべて、スープを作ってみました。それが思ったよりおいしくできたので、つぎの日、おれいにそのスープを持っていきました。おばあさんはとてもよろこんで、「今度はうちでいっしょに作りましょう」と言ってくれました。今では毎週日曜日におばあさんの家に行って、料理を習っています。町に友だちができたのは、あのだいこんのおかげだと思っています。","q":[{"q":"「わたし」はどうして困りましたか。","o":["料理の作り方を聞く人がいなかったから","だいこんが大きくて家に持って帰れなかったから","もらっただいこんの使い方が分からなかったから","町に知っている人が一人もいなかったから"],"a":2,"why":"El motivo del apuro aparece justo antes: «どう使えばいいか分からなくて困りました» (no sabía cómo usar el rábano); no conocer a nadie es el contexto, no la causa del apuro."},{"q":"「それ」は何ですか。","o":["おばあさんがくれただいこん","おばあさんが作った料理","「わたし」が作ったスープ","インターネットで見た作り方"],"a":2,"why":"«それが思ったよりおいしくできた» se refiere a lo inmediatamente anterior: la sopa que preparó «わたし» (スープを作ってみました)."},{"q":"「わたし」は今、どう思っていますか。","o":["おばあさんにもっといろいろな物をあげたい","料理が上手になったので、もう習わなくてもいい","東京のほうが住みやすかったので、早く帰りたい","だいこんのおかげで町に友だちができてよかった"],"a":3,"why":"La última frase, «町に友だちができたのは、あのだいこんのおかげだ», expresa lo que siente ahora; las otras opciones no aparecen en el texto."}]},{"id":"mk-n4-c4-2","lv":"N4","t":"readm","p":"木下さん\n\nおつかれさまです。山本です。\n来月から新しく入る社員のかんげい会について、お知らせします。日にちは四月十日の金曜日、ばしょは会社の近くの「はなの木」というレストランです。時間は七時からですが、その日は五時半にかいぎが終わるよていなので、終わってからみんなで歩いて行こうと思っています。\nかいひは一人三千円です。とうじつお店で集めますが、新しい社員の分はみんなで出すので、三千五百円ずつになります。\nそれから、木下さんにおねがいがあります。かんげい会で、みんなから新しい社員に小さなプレゼントをわたしたいのですが、わたしは来週しゅっちょうで東京にいないので、代わりに買っておいてもらえませんか。五千円ぐらいで、仕事で使えるものがいいと思います。\n行けるかどうか、水曜日までにへんじをください。\nよろしくおねがいします。","q":[{"q":"木下さんは、お店でいくら払いますか。","o":["五百円","三千五百円","五千円","三千円"],"a":1,"why":"La cuota es de 3000 yenes, pero la parte del nuevo empleado la pagan entre todos, así que cada uno paga 3500 (五千円 es el precio del regalo, no la cuota)."},{"q":"山本さんは木下さんに何をおねがいしていますか。","o":["新しい社員へのプレゼントを買っておくこと","レストランに電話してよやくしておくこと","かんげい会のお金をお店で集めること","新しい社員をレストランまでつれて行くこと"],"a":0,"why":"La petición es «代わりに買っておいてもらえませんか» (comprar el regalo); recoger el dinero lo hace el propio 山本 el día de la fiesta, y de la reserva no se habla."},{"q":"山本さんはどうして自分でプレゼントを買わないのですか。","o":["木下さんのほうが新しい社員をよく知っているから","来週はしゅっちょうで東京にいないから","かいぎがあって、お店に行く時間がないから","来週、しゅっちょうで東京へ行くから"],"a":1,"why":"«東京にいない» significa que estará fuera de Tokio (su ciudad) por el viaje de trabajo; la trampa es leerlo como «va a Tokio»."}]},{"id":"mk-n4-c4-3","lv":"N4","t":"readm","p":"ねる前にけいたい電話を見る人が多いそうです。ある会社が二十さいから四十さいの千人に聞いたところ、七十パーセントの人が「ベッドに入ってからも三十分以上けいたいを見ている」と答えました。\n医者によると、ねる前に明るいがめんを見ると、体が「まだ昼だ」と思ってしまって、ねむりにくくなるそうです。朝起きて「よくねたのに、まだつかれている」とかんじる人は、これが理由かもしれません。\nでは、どうすればいいでしょうか。医者は「ねる一時間前にはけいたいを別のへやにおくのがいちばんいい」と言っています。しかし、めざまし時計にけいたいを使っている人には、それはむずかしいでしょう。そういう人は、がめんを暗くして、ベッドの中で見ないようにするだけでもいいそうです。\nわたしも先週からやっていますが、朝の気分が少しかわったように思います。大切なのは、むずかしいことを始めることではなく、できることを毎日つづけることだと思います。","q":[{"q":"「これ」は何ですか。","o":["けいたいをめざまし時計に使うこと","ねる前に明るいがめんを見ること","三十分以上ベッドの中にいること","朝、早い時間に起きること"],"a":1,"why":"«これが理由かもしれません» remite a la frase anterior: mirar una pantalla brillante antes de dormir hace que cueste dormirse."},{"q":"医者が「いちばんいい」と言っているのはどれですか。","o":["ベッドの中でがめんを暗くして見ること","一日に三十分だけけいたいを見ること","ねる一時間前にけいたいを別のへやにおくこと","けいたいをめざまし時計に使わないこと"],"a":2,"why":"El texto dice «別のへやにおくのがいちばんいい»; oscurecer la pantalla es la segunda opción, la que vale «〜だけでもいい»."},{"q":"この文を書いた人がいちばん言いたいことは何ですか。","o":["日本人はけいたいを見る時間が長すぎる","医者の言うことはかならず聞いたほうがいい","ねる前にけいたいを見るのはやめるべきだ","できることを毎日つづけるのが大切だ"],"a":3,"why":"La última frase, «大切なのは…できることを毎日つづけること», es la idea central del autor; las otras opciones son solo un detalle del texto o exageran lo dicho."}]},{"id":"mk-n4-c4-4","lv":"N4","t":"readm","p":"日曜日の朝、ゆうたは父に「今日、友だちと海に行きたいんだけど、自転車を使ってもいい？」と聞きました。父は「いいよ。でも、午後から雨が降るって言ってたから、早く帰ってきなさい」と答えました。ゆうたは「分かった」と言って出かけました。\nしかし、海で友だちとあそんでいるうちに、空が暗くなってきたことに気がつきませんでした。雨が降り始めたとき、ゆうたたちは自転車をおいたばしょからかなり遠いところにいました。かさも持っていなかったので、三人ともぬれて帰りました。\n家に着くと、父は何も言わずにタオルを持ってきてくれました。ゆうたは「ごめん。雨のこと、忘れてた」と小さい声で言いました。父はわらって「ぬれたのはしかたがない。でも、今度から天気を見てから出かけるようにしなさい」と言いました。ゆうたは、おこられると思っていたので、ほっとしました。そして、つぎからは父の言うことをちゃんと聞こうと思いました。","q":[{"q":"ゆうたが出かける前に、父は何と言いましたか。","o":["雨が降るから、早く帰ってくるように言った","自転車ではなく電車で行くように言った","雨が降るから、海に行かないように言った","かさを持って行くように言った"],"a":0,"why":"El padre da permiso («いいよ») y añade «早く帰ってきなさい»; no prohíbe ir ni menciona el paraguas ni el tren."},{"q":"ゆうたたちはどうしてぬれて帰りましたか。","o":["海でおよいでいて、出るのがおそくなったから","かさを海に忘れてきてしまったから","遠くであそんでいて、雨に気がつかなかったから","友だちが帰りたくないと言ったから"],"a":2,"why":"La causa es «空が暗くなってきたことに気がつきませんでした» estando lejos de las bicicletas; el paraguas no lo olvidaron, es que no lo llevaban."},{"q":"ゆうたはどうしてほっとしましたか。","o":["父が天気の見方を教えてくれたから","父がおこらなかったから","父がタオルを持ってきてくれたから","友だちもみんなぬれていたから"],"a":1,"why":"«おこられると思っていたので、ほっとしました»: se tranquilizó porque el padre no lo regañó; la toalla es un hecho, no el motivo del alivio."}]},{"id":"mk-n4-c4-5","lv":"N4","t":"readm","p":"さくらマンションにお住まいのみなさまへ\n\nエレベーター工事のお知らせ\n\nいつもありがとうございます。古くなったエレベーターを新しいものにかえる工事を、下のとおり行います。工事の間、エレベーターは使えません。かいだんをりようしてください。\n\n日時：十一月四日（火）午前九時 から 十一月七日（金）午後五時まで\n※七日は、工事が早く終わった場合、終わった時間からすぐに使えるようになります。\n\n・工事中は大きな音が出ることがあります。\n・大きなにもつを運ぶよていのある方は、工事の前か後にしてください。\n・足の悪い方や、お年をとった方で、買い物などにお困りの方は、かんりにん室までお知らせください。工事の間、一日一回、朝十時にスタッフが手つだいにうかがいます。\n・工事の時間がかわる場合は、入り口のけいじばんでお知らせします。\n\nごめいわくをおかけしますが、よろしくおねがいします。\n\nかんりにん　木下","q":[{"q":"十一月七日の午後三時に工事が終わりました。エレベーターはいつから使えますか。","o":["八日の午前九時から","七日の午後五時から","七日の午後六時から","七日の午後三時から"],"a":3,"why":"«早く終わった場合、終わった時間からすぐに使える»: si acaba a las tres, se usa desde las tres, sin esperar a las cinco."},{"q":"工事の間、買い物に困っている人はどうすればいいですか。","o":["入り口のけいじばんに名前を書く","朝十時にスタッフに電話する","かんりにん室に知らせる","工事の前に買い物をしておく"],"a":2,"why":"El aviso dice «お困りの方はかんりにん室までお知らせください»; el tablón de la entrada solo sirve para avisar de cambios de horario."},{"q":"大きなにもつを運びたい人は、いつ運ぶのがいいですか。","o":["四日の午前九時より後か、七日の午後五時より前","四日の午前九時より前か、七日の午後五時より後","七日の午後五時より前の、都合のいい時間","工事中の、毎日朝十時から十一時までの間"],"a":1,"why":"La obra va del día 4 a las 9:00 al día 7 a las 17:00, y hay que mover las cosas «工事の前か後», es decir, fuera de ese periodo."}]},{"id":"mk-n4-c4-6","lv":"N4","t":"info","p":"みどり しみんプール ごりようあんない\n\n【開いている時間】\nへいじつ：午前十時〜午後九時\n土・日・休日：午前九時〜午後六時\n※毎週月曜日は休みです。\n\n【料金（二時間まで）】\n大人（高校生以上）：五百円\n子ども（小・中学生）：二百円\n小学生より小さい子：むりょう（大人といっしょに入ってください）\n※二時間をすぎると、三十分ごとに大人百円、子ども五十円がかかります。\n※十回使えるカードは、大人四千円、子ども千五百円です。\n\n【注意】\n・水着とぼうしがない方は入れません。レンタルは水着三百円、ぼうし百円です。\n・小学生だけで来る場合は、午後五時までに出てください。","q":[{"q":"土曜日に、大人一人、中学生一人、四さいの子ども一人が三時間プールにいました。ぜんぶでいくらですか。","o":["千二百円","七百円","千円","九百円"],"a":2,"why":"Adulto 500 + 200 de recargo (dos medias horas), estudiante de secundaria 200 + 100, y el niño de cuatro años gratis: 1000 yenes en total; olvidar el recargo o cobrar al pequeño da las otras cifras."},{"q":"小学生二人だけで日曜日にプールへ行きます。何時までに出なければなりませんか。","o":["午後六時","午後四時","午後五時","午後九時"],"a":2,"why":"El domingo cierra a las seis, pero los escolares que van solos deben salir antes de las cinco (condición del apartado 注意)."}]},{"id":"mk-n4-c4-7","lv":"N4","t":"info","p":"秋の日帰りバス旅行 〜もみじの山とおんせん〜\n\n日にち：十月二十五日（土）、十月二十六日（日）、十一月一日（土）\n集合：午前七時四十五分　さくら駅 北口\n出発：午前八時　　帰り：午後六時ごろ さくら駅\n\n料金（バス・昼ご飯・おんせんのお金が入っています）\n大人：七千円\n子ども（四さい〜十二さい）：四千円\n三さい以下：むりょう\n\n申しこみ：十月十五日まで。電話またはホームページから。\n※十月十日までに申しこむと、大人は五百円安くなります。\n※一度に四人以上で申しこむと、ぜんいんが三百円安くなります（上の五百円といっしょには使えません）。\n※雨でも行きますが、台風の場合は中止です。中止のときは前の日の午後六時までに電話でお知らせします。\n\n持ち物：タオル、歩きやすいくつ","q":[{"q":"山口さんは十月八日に、大人二人と十さいの子ども一人で申しこみました。ぜんぶでいくらですか。","o":["一万六千百円","一万七千円","一万八千円","一万七千五百円"],"a":1,"why":"Al apuntarse antes del día 10, cada adulto paga 6500 (7000 − 500) y el niño de diez años 4000: 17000 en total; como son tres personas no se aplica el descuento de grupo."},{"q":"旅行の日に台風が来そうです。中止かどうか、どうやって分かりますか。","o":["前の日の午後六時までに電話がかかってくる","十月十五日までに電話して聞く","旅行の日の朝、さくら駅でスタッフに聞く","旅行の日の朝、ホームページで見る"],"a":0,"why":"El aviso dice que la cancelación se comunica «前の日の午後六時までに電話で»; no confundir con la forma de inscribirse."}]},{"id":"mk-n4-c4-8","lv":"N4","t":"info","p":"ひがし図書館 ごりようあんない\n\n開館時間　火〜金：午前九時三十分〜午後八時\n　　　　　土・日：午前九時三十分〜午後五時\n休館日　　毎週月曜日、毎月さいごの日、十二月二十九日〜一月三日\n\n借りられる数ときかん\n　本・ざっし　一人十さつまで　二週間\n　CD・DVD　一人三つまで　一週間\n※一回だけ、同じきかんのばすことができます（ほかの人が待っている本はのばせません）。\n※かえすのがおそくなった場合、おそくなった日数と同じ日数、新しく借りることができません。\n\nカードを作るには\n　ひがし区に住んでいる人、またはひがし区で働いている人・学校に通っている人が作れます。\n　じゅうしょが分かるもの（運転めんきょなど）を持って、カウンターへ来てください。\n\nかえすばしょ\n　開いている時間はカウンターへ。閉まっているときは入り口のよこのポストへ（CD・DVDはポストに入れないでください）。","q":[{"q":"本をかえすのが五日おそくなりました。この人はどうなりますか。","o":["つぎからは五さつしか借りられない","五日分のお金を払わなければならない","一週間、図書館に入れない","五日間、新しく本を借りられない"],"a":3,"why":"«おそくなった日数と同じ日数、新しく借りることができません»: cinco días sin poder sacar libros; no hay multa en dinero ni prohibición de entrar."},{"q":"ひがし図書館のカードを作れないのはどの人ですか。","o":["となりの区に住んでいて、ひがし区でよく買い物をする人","となりの区に住んでいて、ひがし区の会社で働く人","ひがし区に先月引っこしてきた、仕事がない人","ひがし区の高校に通っている、となりの区の学生"],"a":0,"why":"Solo puede hacerse la tarjeta quien vive, trabaja o estudia en el distrito; hacer la compra allí no cumple ninguna condición."}]},{"id":"mk-n4-c4-9","lv":"N4","t":"info","p":"みなと町 レンタル自転車\n\nばしょ：みなと駅 南口（かんこうあんないじょのよこ）\n時間：午前八時〜午後七時（十二月〜二月は午後五時まで）\n\n料金\n　ふつうの自転車　　二時間まで 四百円　　一日 八百円\n　電動自転車　　　　二時間まで 七百円　　一日 千二百円\n※「一日」は、借りた日の閉まる時間までです。\n※時間をすぎた場合、三十分ごとに二百円かかります。\n※自転車は借りたばしょにかえしてください。ほかのばしょにはかえせません。\n\n申しこみにひつようなもの\n・名前とじゅうしょが分かるもの（パスポート、運転めんきょなど）\n・十八さい以下の方は、大人の方といっしょに来てください。\n\n雨の日は、かさではなくレインコートを使ってください。かさをさしながらのることはできません。\nレインコートは一まい二百円で売っています。","q":[{"q":"七月に、朝九時にふつうの自転車を「一日」で借りて、午後八時にかえしました。いくら払いますか。","o":["千円","千二百円","千六百円","八百円"],"a":1,"why":"En julio cierra a las siete, así que devolver a las ocho supone una hora de más: dos tramos de media hora a 200 = 400; 800 + 400 = 1200 yenes."},{"q":"十六さいの高校生が自転車を借りるには、どうすればいいですか。","o":["大人に電話してもらってから、一人で行く","名前とじゅうしょが分かるものを持って、大人といっしょに行く","運転めんきょを持っている友だちといっしょに行く","名前とじゅうしょが分かるものを持って、一人で行く"],"a":1,"why":"Hacen falta las dos cosas: un documento con nombre y dirección y, al tener 18 años o menos, ir acompañado de un adulto."}]},{"id":"mk-n4-c4-10","lv":"N4","t":"read","p":"ゆきへ\nお母さんは今日、仕事がおそくなります。晩ご飯はれいぞうこにカレーがあるので、あたためて食べてください。ご飯は作ってないので、おこめを三合たいておいてくれるとたすかります。お父さんは八時ごろ帰ると言っていました。食べ終わったら、おさらはあらわなくていいので、水につけておいてください。\n母","q":[{"q":"ゆきさんがしなければならないことは何ですか。","o":["おさらをあらうこと","ご飯をたくこと","カレーを作ること","お父さんの晩ご飯を作ること"],"a":1,"why":"El curri ya está hecho y los platos no hace falta lavarlos; lo único que se le pide es cocer el arroz (おこめを三合たいておいて)."}]},{"id":"mk-n4-c4-11","lv":"N4","t":"read","p":"林先生\nおはようございます。三年二くみのマリアです。\n今朝からねつが三十八度あって、あたまもいたいので、今日は学校を休みます。午前中に病院へ行くつもりです。\n今日出すはずだった作文は、学校に行けるようになったら持っていきます。おそくなってすみません。\nそれから、来週の月曜日の試験のことで質問があるのですが、メールでしてもいいですか。\nマリア","q":[{"q":"マリアさんは今日、何をしますか。","o":["病院に行く","午前中だけ学校に行く","林先生に試験の質問をしに行く","作文を学校に持っていく"],"a":0,"why":"Hoy falta a clase y va al hospital por la mañana; la redacción la llevará cuando pueda volver, y la pregunta del examen la haría por correo."},{"q":"マリアさんは作文をいつ出しますか。","o":["また学校に行けるようになった日","今日の午前中、病院へ行く前","今日のうちにメールで","来週の月曜日の試験の日"],"a":0,"why":"«学校に行けるようになったら持っていきます»: la entregará el día que pueda volver a clase, sin fecha fija."}]},{"id":"mk-n4-c4-12","lv":"N4","t":"read","p":"おきゃくさまへ\nこの店は、三月三十一日（火）で、このばしょでのえいぎょうを終わります。長い間ありがとうございました。\n四月十五日からは、駅前のビルの二かいで新しく開きます。新しい店はいまより広く、カフェもできます。\n三月中にこの店で三千円以上お買い上げのおきゃくさまには、新しい店で使える五百円のけんをさしあげます。\nきたやま書店","q":[{"q":"この店について、正しいものはどれですか。","o":["三月三十一日から駅前の新しい店が開く","新しい店で三千円以上買うと五百円のけんがもらえる","四月十五日まで、この店でカフェが使える","四月十五日から駅前の新しい店で買い物ができる"],"a":3,"why":"La tienda nueva abre el 15 de abril; el vale lo recibe quien compre más de 3000 yenes en marzo en la tienda actual, y se usa en la nueva; la cafetería estará en la tienda nueva."}]},{"id":"mk-n4-c4-13","lv":"N4","t":"read","p":"今日ははじめて一人で電車にのって、おばあちゃんの家に行った。駅でのりかえをまちがえて、はんたいの電車にのってしまった。気がついたときはもう三つ先の駅だった。急いでもどったけれど、おばあちゃんの家に着いたのはやくそくの時間より一時間おそかった。おばあちゃんは「来てくれただけでうれしいよ」と言って、昼ご飯を出してくれた。おこられなくてよかったけれど、つぎは地図をちゃんと見てからのろうと思う。","q":[{"q":"この人はどうして一時間おそくなりましたか。","o":["地図を家に忘れてきたから","駅から家までの道が分からなかったから","おばあちゃんの家が遠くにあるから","まちがった電車にのったから"],"a":3,"why":"«はんたいの電車にのってしまった» y tuvo que volver desde tres estaciones más allá; el mapa solo aparece como propósito para la próxima vez."},{"q":"この人は今、どんな気持ちですか。","o":["一人で電車にのるのはもういやだと思っている","おこられなくて安心したが、つぎは気をつけようと思っている","一時間もおそくなって、まだとてもかなしい","おばあちゃんが何も言わなかったのでふあんだ"],"a":1,"why":"«おこられなくてよかった» y «つぎは地図をちゃんと見てからのろう» muestran alivio y propósito de enmienda."}]}]);

MOCK_Q.push(...[{"id":"mk-n4-c5-1","lv":"N4","t":"listen","lines":[{"s":"A","j":"中山さん、ちょっといいですか。三時のかいぎの紙、十まいコピーしておいてください。"},{"s":"B","j":"はい。あの、二かいのかいぎ室の用意もしましょうか。"},{"s":"A","j":"それは木村さんがやってくれるから、いいですよ。それより、先に川上さんに電話をして、かいぎが三時半になったと言ってください。"},{"s":"B","j":"三時半ですね。わかりました。コピーはその後でいいですか。"},{"s":"A","j":"はい。おねがいします。"}],"q":"中山さんはまず何をしますか。","o":["電話をかける","コピーをする","かいぎ室の用意をする","川上さんの会社に行く"],"a":0,"why":"El jefe dice «先に川上さんに電話をして»: primero llama; la copia va «その後» y la sala la prepara 木村さん."},{"id":"mk-n4-c5-2","lv":"N4","t":"listen","lines":[{"s":"A","j":"すみません、きのうここで買ったシャツなんですが、ほかのものにかえてもらえませんか。"},{"s":"B","j":"はい。何か問題がありましたか。色でしょうか。"},{"s":"A","j":"いいえ、色はすきです。サイズが小さかったんです。家で着てみたら、着られなくて。"},{"s":"B","j":"そうでしたか。では、一つ大きいサイズをお持ちしますね。"},{"s":"A","j":"おねがいします。ああ、それと、このボタン、少しとれそうですね。"},{"s":"B","j":"申しわけありません。新しいものをお持ちします。"}],"q":"女の人はどうしてシャツをかえますか。","o":["色がすきじゃなかったから","サイズが小さかったから","ボタンがとれていたから","ほかの店より高かったから"],"a":1,"why":"Dice «サイズが小さかったんです»; el color sí le gusta y el botón solo «とれそう» (a punto de caerse), no es el motivo."},{"id":"mk-n4-c5-3","lv":"N4","t":"listen","lines":[{"s":"A","j":"すみません、電車の中にかばんを忘れてしまったんですが。"},{"s":"B","j":"どの電車ですか。"},{"s":"A","j":"十分ぐらい前に着いた、東京行きの電車です。黒いかばんです。"},{"s":"B","j":"ここはきっぷの売り場なので、わからないんです。二ばんせんのホームにいる駅員に聞いてみてください。"},{"s":"A","j":"二ばんせんですね。あの、その前にトイレに行ってもいいですか。"},{"s":"B","j":"ええ。でも、電車が出てしまうかもしれませんから、急いだほうがいいですよ。"},{"s":"A","j":"じゃあ、トイレは後にします。"}],"q":"女の人はこれからどこへ行きますか。","o":["二ばんせんのホーム","東京行きの電車の中","きっぷの売り場","トイレ"],"a":0,"why":"Le mandan al andén 2 a preguntar al empleado; dice «トイレは後にします», y la taquilla es donde está ahora."},{"id":"mk-n4-c5-4","lv":"N4","t":"listen","lines":[{"s":"A","j":"いらっしゃいませ。ご注文は。"},{"s":"B","j":"カレーを一つと、コーヒーを一つください。"},{"s":"A","j":"はい。カレーは八百円で、コーヒーは三百円です。あ、今はランチの時間なので、セットにすると千円になりますよ。"},{"s":"B","j":"じゃあ、セットでおねがいします。それから、サラダもつけられますか。"},{"s":"A","j":"はい、サラダは二百円です。"},{"s":"B","j":"うーん、サラダはいいです。セットだけで。"}],"q":"男の人はいくら払いますか。","o":["千二百円","八百円","千円","千百円"],"a":2,"why":"Elige el set de 1000 yenes y rechaza la ensalada («サラダはいいです»); 1100 sería suelto, 1200 con ensalada y 800 solo el curri."},{"id":"mk-n4-c5-5","lv":"N4","t":"listen","lines":[{"s":"A","j":"もしもし、今どこ？"},{"s":"B","j":"駅を出たところ。今から帰るよ。"},{"s":"A","j":"ちょうどよかった。帰りにスーパーでぎゅうにゅうを買ってきてくれない？"},{"s":"B","j":"いいよ。たまごもいる？"},{"s":"A","j":"たまごはきのう買ったからいい。あ、それと、パン。……ううん、パンはわたしが明日買うから、ぎゅうにゅうだけでいいわ。"},{"s":"B","j":"わかった。"}],"q":"男の人は何を買いますか。","o":["たまご","ぎゅうにゅうとパン","ぎゅうにゅう","パン"],"a":2,"why":"Al final ella dice «ぎゅうにゅうだけでいい»: los huevos ya los compró y el pan lo comprará ella mañana."},{"id":"mk-n4-c5-6","lv":"N4","t":"listen","lines":[{"s":"A","j":"先生、来週の漢字のテストは月曜日ですよね。"},{"s":"B","j":"いいえ、月曜日は学校が休みになったので、火曜日にします。"},{"s":"A","j":"火曜日ですか。でも、火曜日は林先生のテストがあります。"},{"s":"B","j":"ああ、そうでしたね。水曜日はわたしが学校に来ませんから、木曜日にしましょう。"},{"s":"A","j":"木曜日ですね。わかりました。"}],"q":"漢字のテストはいつですか。","o":["水曜日","月曜日","火曜日","木曜日"],"a":3,"why":"Se descartan lunes (festivo), martes (otro examen) y miércoles (la profesora no viene); queda «木曜日にしましょう»."},{"id":"mk-n4-c5-7","lv":"N4","t":"listen","lines":[{"s":"A","j":"どうしましたか。"},{"s":"B","j":"おとといから、のどがいたくて、せきが出ます。"},{"s":"A","j":"ねつはありますか。"},{"s":"B","j":"けさは三十七度五分でした。"},{"s":"A","j":"かぜですね。薬を出しますから、一日三回、食事の後に飲んでください。それと、今日はおふろに入らないで、早くねてください。"},{"s":"B","j":"あの、明日、仕事に行ってもいいですか。"},{"s":"A","j":"ねつが下がったら、行ってもいいですよ。"}],"q":"男の人は今日、何をしてはいけませんか。","o":["薬を飲むこと","おふろに入ること","早くねること","明日仕事に行くこと"],"a":1,"why":"El médico dice «おふろに入らないで»; tomar la medicina y dormir pronto son órdenes, y mañana puede trabajar si baja la fiebre."},{"id":"mk-n4-c5-8","lv":"N4","t":"listen","lines":[{"s":"A","j":"きのうの映画、どうだった？"},{"s":"B","j":"うーん、話はおもしろかったけど、長すぎたよ。三時間もあったから。"},{"s":"A","j":"へえ。音楽はよかったって聞いたけど。"},{"s":"B","j":"音楽はよかった。でも、映画館が寒くて。"},{"s":"A","j":"じゃあ、もう一度見たい？"},{"s":"B","j":"ううん、一度でいいかな。"}],"q":"男の人は映画についてどう思っていますか。","o":["話がつまらなかった","もう一度見たい","音楽がよくなかった","長すぎた"],"a":3,"why":"Su queja es «長すぎた»; la historia fue interesante, la música buena y no quiere verla otra vez («一度でいい»)."},{"id":"mk-n4-c5-9","lv":"N4","t":"listen","lines":[{"s":"A","j":"はい、レストランさくらです。"},{"s":"B","j":"今晩七時に四人で食事をしたいんですが、せきはありますか。"},{"s":"A","j":"申しわけありません、七時はいっぱいで……。六時か八時ならだいじょうぶです。"},{"s":"B","j":"六時はちょっと早いですね。じゃあ、八時で。"},{"s":"A","j":"八時ですね。お名前をおねがいします。"},{"s":"B","j":"中村です。あ、ちょっと待ってください。八時だと子どもがねてしまうので、やっぱり六時にします。"},{"s":"A","j":"はい、六時に四人ですね。お待ちしております。"}],"q":"中村さんは何時に店に行きますか。","o":["七時","八時","九時","六時"],"a":3,"why":"Primero elige las ocho, pero cambia: «やっぱり六時にします». Las siete están llenas."},{"id":"mk-n4-c5-10","lv":"N4","t":"listen","lines":[{"s":"A","j":"すみません、この本を借りたいんですが。"},{"s":"B","j":"図書館のカードはお持ちですか。"},{"s":"A","j":"いいえ、まだ作っていません。"},{"s":"B","j":"では、まずカードを作ってください。あちらの紙に名前とじゅうしょを書いて、ここに持ってきてください。"},{"s":"A","j":"はい。本は三さつまで借りられますよね。"},{"s":"B","j":"二さつまでです。それから、二週間のうちにかえしてください。"},{"s":"A","j":"わかりました。"}],"q":"女の人はまず何をしますか。","o":["借りた本をかえす","紙に名前を書く","カードをもらう","本を二さつ借りて帰る"],"a":1,"why":"La bibliotecaria dice «まずカードを作ってください»: hay que rellenar el papel y traerlo; recibir la tarjeta y llevarse libros viene después."},{"id":"mk-n4-c5-11","lv":"N4","t":"listen","lines":[{"s":"A","j":"もしもし、高木です。すみません、少しおそくなります。"},{"s":"B","j":"どうしたんですか。電車が止まっているんですか。"},{"s":"A","j":"いいえ、電車は動いています。道に車が多くて、バスがぜんぜん来ないんです。"},{"s":"B","j":"そうですか。じゃあ、タクシーで来ますか。"},{"s":"A","j":"タクシーも来なくて……。今から駅まで歩いて、電車で行きます。十時には着くと思います。"},{"s":"B","j":"わかりました。気をつけて。"}],"q":"女の人はどうしておそくなりますか。","o":["バスが来ないから","タクシーにのるから","電車が止まっているから","駅まで遠いから"],"a":0,"why":"Explica «バスがぜんぜん来ないんです»; el tren funciona, el taxi tampoco viene e irá andando a la estación."},{"id":"mk-n4-c5-12","lv":"N4","t":"listen","lines":[{"s":"A","j":"明日、友だちが来るから、へやをきれいにしないとね。"},{"s":"B","j":"そうだね。ぼくはトイレのそうじをするよ。"},{"s":"A","j":"トイレはわたしがもうやったから、まどをきれいにしてくれない？"},{"s":"B","j":"いいよ。その前に、せんたくをしておくね。"},{"s":"A","j":"せんたくは夕方でいいよ。それより、先にまどをおねがい。それから二人で買い物に行こう。"},{"s":"B","j":"わかった。"}],"q":"男の人はまず何をしますか。","o":["買い物に行く","まどをきれいにする","せんたくをする","トイレのそうじをする"],"a":1,"why":"Ella pide «先にまどをおねがい»; el baño ya está limpio, la colada puede esperar a la tarde y la compra es después."},{"id":"mk-n4-c5-13","lv":"N4","t":"listen","lines":[{"s":"A","j":"すみません、みなみ病院へはどう行ったらいいですか。"},{"s":"B","j":"ここから歩くと二十分ぐらいかかりますよ。バスなら十分です。"},{"s":"A","j":"バスはどこから出ていますか。"},{"s":"B","j":"北口から出ています。でも、今の時間はバスが一時間に一本しかないので、タクシーのほうがいいかもしれません。"},{"s":"A","j":"うーん、タクシーは高いですから、歩いて行きます。天気もいいし。"},{"s":"B","j":"そうですか。この道をまっすぐですよ。"}],"q":"女の人はどうやって病院へ行きますか。","o":["電車で行く","歩いて行く","バスで行く","タクシーで行く"],"a":1,"why":"Decide «歩いて行きます» porque el bus pasa poco y el taxi es caro; el tren no se menciona como opción."},{"id":"mk-n4-c5-14","lv":"N4","t":"listen","lines":[{"s":"A","j":"父の日のプレゼント、何にしようか。"},{"s":"B","j":"お父さん、おさけがすきだから、おさけはどう？"},{"s":"A","j":"おさけは医者に止められているんだって。"},{"s":"B","j":"じゃあ、ネクタイは？"},{"s":"A","j":"ネクタイは去年あげたよ。セーターもたくさん持っているし。……あ、新しいかばんがほしいって言ってた。"},{"s":"B","j":"じゃあ、それにしよう。"},{"s":"A","j":"でも、かばんは高いなあ。二人でお金を出せば買えるかな。"},{"s":"B","j":"うん、そうしよう。"}],"q":"二人は何を買いますか。","o":["セーター","ネクタイ","おさけ","かばん"],"a":3,"why":"Al final acuerdan el bolso («それにしよう»); el alcohol lo prohibió el médico, la corbata fue el regalo del año pasado y jerséis ya tiene."},{"id":"mk-n4-c5-15","lv":"N4","t":"listen","lines":[{"s":"A","j":"金曜日のパーティー、何人来ますか。"},{"s":"B","j":"うちの会社からは八人です。あ、山本さんは旅行で来られないので、七人ですね。"},{"s":"A","j":"小林さんの会社は？"},{"s":"B","j":"五人だと聞いています。"},{"s":"A","j":"じゃあ、ぜんぶで十二人ですね。"},{"s":"B","j":"あ、すみません、社長も来ると言っていました。"},{"s":"A","j":"じゃあ、十三人分の用意をしましょう。"}],"q":"パーティーには何人来ますか。","o":["十二人","十三人","八人","七人"],"a":1,"why":"7 (8 menos 山本さん) + 5 = 12, y se añade el presidente: «十三人分の用意»."},{"id":"mk-n4-c5-16","lv":"N4","t":"listen","lines":[{"s":"A","j":"今日のしゅくだいは、三十ページの問題です。"},{"s":"B","j":"先生、作文は？"},{"s":"A","j":"作文は来週の月曜日まででいいですよ。それより、明日は漢字のテストがありますから、二十ページの漢字をよく読んでおいてください。"},{"s":"B","j":"書くれんしゅうもしたほうがいいですか。"},{"s":"A","j":"書けなくてもいいです。読めればいいですよ。"}],"q":"学生は明日のテストのために何をしておきますか。","o":["三十ページの問題をする","漢字を読んでおく","漢字を書くれんしゅうをする","作文を書く"],"a":1,"why":"Para el examen la profesora pide «漢字をよく読んでおいて» y aclara que escribir no hace falta; los problemas son los deberes y la redacción es para el lunes."},{"id":"mk-n4-c5-17","lv":"N4","t":"listen","lines":[{"s":"A","j":"日曜日、山に行かない？"},{"s":"B","j":"いいね。でも、天気よほうでは日曜日は雨だって。"},{"s":"A","j":"ほんと？じゃあ、土曜日は？"},{"s":"B","j":"土曜日は午前中、仕事があるんだ。午後からなら行けるけど、山は遠いから……。"},{"s":"A","j":"それなら、来週の日曜日にしようか。"},{"s":"B","j":"そうしよう。はれたらいいね。"}],"q":"二人はいつ山に行きますか。","o":["今週の土曜日","土曜日の午後","来週の日曜日","今週の日曜日"],"a":2,"why":"Este domingo llueve, el sábado él trabaja por la mañana y la tarde es poco tiempo; acuerdan «来週の日曜日»."},{"id":"mk-n4-c5-18","lv":"N4","t":"listen","lines":[{"s":"A","j":"はい、やまと会社です。"},{"s":"B","j":"小川会社の森と申します。上野さんをおねがいします。"},{"s":"A","j":"申しわけありません、上野はただいま外出しております。"},{"s":"B","j":"そうですか。何時ごろ帰りますか。"},{"s":"A","j":"四時ごろ帰るよていです。"},{"s":"B","j":"では、帰ったら、お電話をいただけますか。あ、でも、わたしも五時までかいぎがあるので、五時すぎにおねがいします。"},{"s":"A","j":"はい、五時すぎにお電話するように言っておきます。"}],"q":"上野さんは何をしますか。","o":["五時までかいぎに出る","森さんの会社へ行く","四時ごろに電話をかける","五時すぎに電話をかける"],"a":3,"why":"森さん pide que le llame «五時すぎに»; las cuatro es la hora de vuelta de 上野さん y la reunión hasta las cinco es la de 森さん."},{"id":"mk-n4-c5-19","lv":"N4","t":"listen","lines":[{"s":"A","j":"ケーキ、食べない？"},{"s":"B","j":"ありがとう。でも、今はいいや。"},{"s":"A","j":"えっ、あまいもの、すきだよね。おなかがいっぱい？"},{"s":"B","j":"いや、おなかはすいているんだけど、今、はがいたくて。来週、はいしゃに行くんだ。"},{"s":"A","j":"そう。じゃあ、お茶だけ飲む？"},{"s":"B","j":"うん、もらう。あつくないのをおねがい。"}],"q":"男の人はどうしてケーキを食べませんか。","o":["あついものが食べられないから","はがいたいから","おなかがいっぱいだから","あまいものがすきじゃないから"],"a":1,"why":"Dice «はがいたくて»; no está lleno, sí le gusta el dulce, y lo de «あつくない» es solo para el té."},{"id":"mk-n4-c5-20","lv":"N4","t":"listen","lines":[{"s":"A","j":"このにもつをおおさかまで送りたいんですが。"},{"s":"B","j":"はい。急ぎますか。明日着くのは千二百円、あさって着くのは千円、三日かかるのは八百円です。"},{"s":"A","j":"うーん、金曜日までに着けばいいので、三日かかるのでおねがいします。"},{"s":"B","j":"はい。中は何ですか。"},{"s":"A","j":"本と服です。"},{"s":"B","j":"では、こちらに送る人の名前とじゅうしょを書いてください。"}],"q":"女の人はいくら払いますか。","o":["千円","二千円","千二百円","八百円"],"a":3,"why":"Elige el envío de tres días, «八百円»; 1000 y 1200 son las opciones más rápidas que rechaza."},{"id":"mk-n4-c5-21","lv":"N4","t":"resp","j":"すみません、この電車は東京駅に止まりますか。","o":["東京駅まで行ってきました。","ええ、止めてもいいですよ。","いいえ、止まりませんよ。","はい、東京駅はいいところですね。"],"a":2,"why":"Pregunta si el tren para en la estación de Tokio; lo natural es contestar sí o no. «止めてもいい» confunde parar (止まる) con aparcar (止める); las otras hablan del lugar, no de si el tren para."},{"id":"mk-n4-c5-22","lv":"N4","t":"resp","j":"今度の土曜日、いっしょに映画を見に行きませんか。","o":["ええ、ぜひ。何時ですか。","いいえ、見ませんでした。","はい、先週見に行きました。","ええ、見てもいいです。"],"a":0,"why":"Es una invitación (〜ませんか): se acepta y se concreta la hora. Las otras responden en pasado o dan permiso, como si fuera otra pregunta."},{"id":"mk-n4-c5-23","lv":"N4","t":"resp","j":"先週はいろいろお世話になりました。","o":["どうぞ、お大事に。","では、おじゃまします。","いいえ、こちらこそ。","どうぞ、こちらへ。"],"a":2,"why":"Ante un agradecimiento por la ayuda recibida se responde «こちらこそ». «お大事に» es para enfermos y las otras son fórmulas de entrada o invitación."},{"id":"mk-n4-c5-24","lv":"N4","t":"resp","j":"この紙、明日までにコピーしておいてくれる？","o":["ええ、コピーしてください。","はい、何まいですか。","はい、きのうコピーしました。","いいえ、明日は来ません。"],"a":1,"why":"Es una petición: se acepta y se pregunta cuántas copias. «コピーしてください» devuelve la orden a quien la pidió."},{"id":"mk-n4-c5-25","lv":"N4","t":"resp","j":"木村さん、元気がないですね。だいじょうぶですか。","o":["ええ、朝、顔をあらいました。","ええ、ちょっとあたまがいたくて。","いいえ、どうぞお大事に。","はい、だいじょうぶそうですね。"],"a":1,"why":"Le preguntan por su estado: explica que le duele la cabeza. «お大事に» y «だいじょうぶそうですね» son lo que diría quien pregunta, no quien responde."},{"id":"mk-n4-c5-26","lv":"N4","t":"resp","j":"あの、ここに車を止めてもいいですか。","o":["はい、もう車を止めましたよ。","いいえ、車は持っていません。","すみません、ここはだめです。","ええ、止めないでください。"],"a":2,"why":"Pide permiso para aparcar; se concede o se niega. «ええ、止めないでください» es contradictorio (afirma y prohíbe)."},{"id":"mk-n4-c5-27","lv":"N4","t":"resp","j":"どうぞ、入ってください。","o":["ただいま帰りました。","おじゃまします。","いってきます。","いらっしゃいませ。"],"a":1,"why":"Al entrar en casa ajena se dice «おじゃまします». «いらっしゃい» lo dice el anfitrión; «いってきます» y «ただいま» son para salir y volver a la propia casa."},{"id":"mk-n4-c5-28","lv":"N4","t":"resp","j":"すみません、トイレはどこですか。","o":["一回三百円です。","朝十時から開いています。","はい、手をあらってきますね。","エレベーターのとなりです。"],"a":3,"why":"Pregunta por un lugar (どこ), así que se indica dónde está; las otras responden a hora o precio o confunden quién va al baño."},{"id":"mk-n4-c5-29","lv":"N4","t":"resp","j":"来週のかいぎ、何時からだっけ？","o":["かいぎ室だよ。","三時間ぐらいだよ。","午後二時からだよ。","先週だったよ。"],"a":2,"why":"Pregunta la hora de inicio (何時から). «かいぎ室» responde dónde, «三時間» a cuánto dura y «先週» confunde la semana."},{"id":"mk-n4-c5-30","lv":"N4","t":"resp","j":"重そうですね。お持ちしましょうか。","o":["はい、持ってくださいね。","すみません、おねがいします。","いいえ、重くないほうがいいです。","どうぞ、持ちましょう。"],"a":1,"why":"Ante un ofrecimiento cortés se agradece y se acepta con «おねがいします». «持ってください» suena a orden y «どうぞ、持ちましょう» invierte los papeles."},{"id":"mk-n4-c5-31","lv":"N4","t":"resp","j":"ご注文は何にしますか。","o":["もう少し待ってください。","ごちそうさまでした。","はい、お水をどうぞ。","はい、とてもおいしかったです。"],"a":0,"why":"El camarero pide el pedido; se puede pedir más tiempo. Las otras son para después de comer o cosas que diría el propio camarero."},{"id":"mk-n4-c5-32","lv":"N4","t":"resp","j":"すみません、このりんご、一ついくらですか。","o":["はい、一つください。","五時までです。","三つあります。","百五十円です。"],"a":3,"why":"Pregunta el precio (いくら): se contesta con una cantidad en yenes. «一つください» es lo que diría el cliente, no el vendedor."},{"id":"mk-n4-c5-33","lv":"N4","t":"resp","j":"おそくなって、すみません。","o":["ええ、では、お先に帰りますね。","いいえ、もう帰りました。","いいえ、今来たところですよ。","はい、ゆっくりどうぞ。"],"a":2,"why":"Ante una disculpa por llegar tarde se tranquiliza: «yo también acabo de llegar». Las otras no encajan con una disculpa."},{"id":"mk-n4-c5-34","lv":"N4","t":"resp","j":"あ、雨が降ってきた。かさ、持ってる？","o":["うん、雨はすきだよ。","うん、きのうも降ったね。","うん、いっしょに入ろう。","ううん、かさは高いね。"],"a":2,"why":"Pregunta si lleva paraguas para compartirlo; «いっしょに入ろう» responde a eso. Las otras hablan de la lluvia o del precio, no de si lo tiene."}]);

